pff-webview-harness:
EBWebView
param([string]$Out, [string]$Process = 'orca-slicer')
# Captures the process's main window from the screen (not PrintWindow, which
# renders GL black and omits modals). Needs a connected RDP session.
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class Win {
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
}
"@
[Win]::SetProcessDPIAware() | Out-Null
$p = Get-Process $Process | Where-Object MainWindowHandle -ne 0 | Select-Object -First 1
"window: $($p.MainWindowTitle)"
[Win]::SetForegroundWindow($p.MainWindowHandle) | Out-Null
Start-Sleep -Milliseconds 400
$r = New-Object Win+RECT
[Win]::GetWindowRect($p.MainWindowHandle, [ref]$r) | Out-Null
$w = $r.Right - $r.Left; $h = $r.Bottom - $r.Top
$bmp = New-Object System.Drawing.Bitmap $w, $h
$g = [System.Drawing.Graphics]::FromImage($bmp)
$g.CopyFromScreen($r.Left, $r.Top, 0, 0, $bmp.Size)
$bmp.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
"$Out ${w}x${h}"
param([int]$X, [int]$Y)
# Clicks at window-relative real pixels ($X, $Y) in the app's main window.
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class M {
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
  [DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y);
  [DllImport("user32.dll")] public static extern void mouse_event(uint f, uint dx, uint dy, uint d, UIntPtr e);
}
"@
[M]::SetProcessDPIAware() | Out-Null
$p = Get-Process orca-slicer | Where-Object MainWindowHandle -ne 0 | Select-Object -First 1
[M]::SetForegroundWindow($p.MainWindowHandle) | Out-Null
$r = New-Object M+RECT
[M]::GetWindowRect($p.MainWindowHandle, [ref]$r) | Out-Null
[M]::SetCursorPos($r.Left + $X, $r.Top + $Y) | Out-Null
Start-Sleep -Milliseconds 300
[M]::mouse_event(2, 0, 0, 0, [UIntPtr]::Zero)
[M]::mouse_event(4, 0, 0, 0, [UIntPtr]::Zero)
param([string]$Model)
# Opens the import dialog with Ctrl+I in the app's main window and imports $Model.
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W { [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, System.Text.StringBuilder s, int n); }
"@
$p = Get-Process orca-slicer | Where-Object MainWindowHandle -ne 0 | Select-Object -First 1
[W]::SetForegroundWindow($p.MainWindowHandle) | Out-Null
Start-Sleep -Milliseconds 500
[System.Windows.Forms.SendKeys]::SendWait('^i')
Start-Sleep -Seconds 3
$sb = New-Object System.Text.StringBuilder 256
[W]::GetWindowTextW([W]::GetForegroundWindow(), $sb, 256) | Out-Null
"dialog: $sb"
[System.Windows.Forms.SendKeys]::SendWait($Model)
Start-Sleep -Milliseconds 500
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
// Scratch DevTools driver for the WebView2 pages.
//   node cdp.mjs list
//   node cdp.mjs eval <urlSubstring> <js>
//   node cdp.mjs shot <urlSubstring> <out.png>
import { writeFileSync } from 'node:fs';

const [, , command, match, arg] = process.argv;
const targets = await (await fetch('http://127.0.0.1:9333/json/list')).json();
if (command === 'list') {
  for (const t of targets) console.log(t.type, t.url.slice(0, 120), t.title);
  process.exit(0);
}
const pages = targets.filter((t) => t.type === 'page' && t.url.includes(match));
if (pages.length === 0) {
  console.error('no page matches', match);
  process.exit(2);
}
const socket = new WebSocket(pages[0].webSocketDebuggerUrl);
await new Promise((resolve) => socket.addEventListener('open', resolve));
let next = 0;
const call = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++next;
    const listener = (event) => {
