param([string]$Out, [string]$Process = 'shell_integration_harness')
# Whole-screen capture plus a list of the process's top-level windows.
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class W7 {
  public delegate bool Enum(IntPtr h, IntPtr l);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L, T, R, B; }
  [DllImport("user32.dll")] public static extern bool EnumWindows(Enum e, IntPtr l);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint p);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassNameW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
}
"@
[W7]::SetProcessDPIAware() | Out-Null
$ids = @(Get-Process $Process -ErrorAction SilentlyContinue | ForEach-Object Id)
[W7]::EnumWindows({ param($h, $l)
    $procId = 0; [W7]::GetWindowThreadProcessId($h, [ref]$procId) | Out-Null
    if ($ids -contains $procId -and [W7]::IsWindowVisible($h)) {
        $t = New-Object Text.StringBuilder 256; [W7]::GetWindowTextW($h, $t, 256) | Out-Null
        $c = New-Object Text.StringBuilder 128; [W7]::GetClassNameW($h, $c, 128) | Out-Null
        $r = New-Object W7+RECT; [W7]::GetWindowRect($h, [ref]$r) | Out-Null
        "window [$t] class=$c rect=$($r.L),$($r.T),$($r.R),$($r.B)"
    }
    $true }, [IntPtr]::Zero) | Out-Null
$b = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
"screen $($b.Width)x$($b.Height)"
$bmp = New-Object System.Drawing.Bitmap $b.Width, $b.Height
$g = [System.Drawing.Graphics]::FromImage($bmp)
$g.CopyFromScreen($b.Left, $b.Top, 0, 0, $bmp.Size)
$bmp.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
"saved $Out"

