518	bool has_block(const json& messages, const std::string& type)
519	{
520	    for (const json& message : messages)
521	        if (message["content"].is_array())
522	            for (const json& block : message["content"])
523	                if (block.value("type", "") == type)
524	                    return true;
525	    return false;
526	}
