530	TEST_CASE("Anthropic accepts a turn that replays its thinking with a fired skill still in place, an OpenAI call id in its history",
531	          "[agent][anthropic][live][.]")
532	{
533	    if (anthropic_key().empty())
534	        SKIP("ANTHROPIC_API_KEY is not set");
535	    std::vector<AgentHttpRequest> sent;
536	    std::vector<AgentUsage>       usage;
537	    AgentServicePtr               agent = live_anthropic_agent(sent, usage, /*enforce_history_check=*/true);
538	
