540	
541	    JusPrinTest::kept_nowhere(request);
542	    request.request_id                = "live-anthropic-history";
543	    request.session.instructions      = "You are a connectivity check. First call the workspace_inspect tool once, with sections "
544	                                        "[\"summary\"]. When its result arrives, reply with the single word: checked.";
545	    request.session.include_workspace = false;
546	    request.conversation              = {{"user", "Is anything on the plate?"}, openai_minted_call(), {"assistant", "One object."}};
547	    request.user_text                 = "Run the check.";
548	    request.skills = {AgentSkillUse{"file-loaded", "A file was loaded. This note is part of the check; act on the instructions.",
549	                                    nullptr, "file_loaded"}};
550	    REQUIRE(agent->start(request));
551	    const Turn first = run_until_settled(*agent);
552	    INFO("first reply: " << first.text << (first.error ? " error: " + first.error->code + " " + first.error->message : ""));
553	    REQUIRE_FALSE(first.error);
554	    REQUIRE(first.call);
555	
556	    REQUIRE(agent->continue_after_tool({first.call->call_id, "succeeded", R"({"state":"succeeded","result":{"summary":{"objects":1}}})"}));
557	    const Turn second = run_until_settled(*agent);
558	    report(usage);
559	    INFO("second reply: " << second.text << (second.error ? " error: " + second.error->code + " " + second.error->message : ""));
560	    // Accepted under an enforced history check: the history did not change.
561	    REQUIRE_FALSE(second.error);
562	    CHECK(second.completed);
563	    REQUIRE(sent.size() == 2);
564	    const json messages = json::parse(sent.back().body)["messages"];
565	    // What the check covered: the skill, still in place, before replayed
566	    // thinking. Without a thinking block in the first response there was
567	    // nothing for the check to reject.
568	    const bool skill_in_place = sent.back().body.find("A file was loaded.") != std::string::npos;
569	    const bool thinking_replayed = has_block(messages, "thinking") || has_block(messages, "redacted_thinking");
570	    WARN("history check: skill in place " << skill_in_place << ", thinking replayed " << thinking_replayed);
571	    CHECK(skill_in_place);
572	    CHECK(sent.back().body.find("call_Ab3dE5fG7hI9jK1lM3nO5pQ7") != std::string::npos);
573	}
