575	TEST_CASE("Anthropic writes a title from a conversation with a replayed call, or one that opens on the assistant",
576	          "[agent][anthropic][live][.]")
577	{
578	    if (anthropic_key().empty())
579	        SKIP("ANTHROPIC_API_KEY is not set");
580	    const auto title = [](std::vector<AgentConversationContext> conversation) {
581	        std::vector<AgentHttpRequest> sent;
582	        std::vector<AgentUsage>       usage;
583	        AgentServicePtr               agent = live_anthropic_agent(sent, usage);
584	        AgentRequest                  request;
585	        request.request_id   = "live-anthropic-title";
586	        request.purpose      = AgentRequest::Purpose::ConversationTitle;
587	        request.conversation = std::move(conversation);
588	        REQUIRE(agent->start(request));
589	        const Turn turn = run_until_settled(*agent);
590	        report(usage);
591	        INFO("title: " << turn.text << (turn.error ? " error: " + turn.error->code + " " + turn.error->message : ""));
592	        CHECK_FALSE(turn.error);
593	        CHECK(turn.completed);
594	        CHECK_FALSE(turn.text.empty());
595	        REQUIRE(sent.size() == 1);
596	        return json::parse(sent.front().body);
597	    };
598	    // A tool exchange with an OpenAI id and no tools declared, ending on the
599	    // assistant, so the codec adds "Write the title.".
600	    const json replayed = title({{"user", "Help me print a backpack frame."}, openai_minted_call(), {"assistant", "Use five walls."}});
601	    CHECK_FALSE(replayed.contains("tools"));
