# One self-explaining picture per bug: a heading that says what is wrong, labelled
# panels ("WRONG" / "CORRECT"), and a red box around the exact spot.
Add-Type -AssemblyName System.Drawing
$src = 'C:\b\wk7\bugs'; $dst = 'C:\b\wk7\bugs-labelled'
New-Item -ItemType Directory -Force $dst | Out-Null
Get-ChildItem $dst -Filter *.png | Remove-Item -Force
$red = [System.Drawing.Color]::FromArgb(214, 40, 40); $green = [System.Drawing.Color]::FromArgb(30, 130, 76)
$ink = [System.Drawing.Color]::FromArgb(25, 25, 30); $grey = [System.Drawing.Color]::FromArgb(80, 80, 90)
$titleFont = New-Object System.Drawing.Font 'Segoe UI Semibold', 30
$bodyFont  = New-Object System.Drawing.Font 'Segoe UI', 21
$tagFont   = New-Object System.Drawing.Font 'Segoe UI Semibold', 21
$noteFont  = New-Object System.Drawing.Font 'Segoe UI Semibold', 19

# $panels: @{ File; Crop=@(x,y,w,h) or $null; Scale; Tag; Ok=$true/$false; Note; Marks=@(@(x,y,w,h),...) in source pixels }
function Compose($name, $title, $body, $panels, [int]$width = 1800) {
    $probe = [System.Drawing.Graphics]::FromImage((New-Object System.Drawing.Bitmap 1, 1))
    $inner = $width - 80
    $titleH = [int]$probe.MeasureString($title, $titleFont, $inner).Height + 8
    $bodyH  = [int]$probe.MeasureString($body, $bodyFont, $inner).Height + 8
    $y = 30 + $titleH + $bodyH + 24
    $laid = @()
    foreach ($p in $panels) {
        $img = [System.Drawing.Bitmap]::FromFile($p.File)
        $c = if ($p.Crop) { $p.Crop } else { @(0, 0, $img.Width, $img.Height) }
        $w = [int]($c[2] * $p.Scale); $h = [int]($c[3] * $p.Scale)
        $noteH = if ($p.Note) { [int]$probe.MeasureString($p.Note, $noteFont, $inner).Height + 6 } else { 0 }
        $laid += @{ Img = $img; C = $c; W = $w; H = $h; P = $p; Y = $y; NoteH = $noteH }
        $y += 44 + $noteH + $h + 30
    }
    $bmp = New-Object System.Drawing.Bitmap $width, $y
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.Clear([System.Drawing.Color]::White); $g.SmoothingMode = 'AntiAlias'; $g.InterpolationMode = 'HighQualityBicubic'; $g.TextRenderingHint = 'AntiAliasGridFit'
    $brush = { param($col) New-Object System.Drawing.SolidBrush $col }
    $g.DrawString($title, $titleFont, (& $brush $ink), (New-Object System.Drawing.RectangleF 40, 26, $inner, $titleH))
    $g.DrawString($body, $bodyFont, (& $brush $grey), (New-Object System.Drawing.RectangleF 40, (26 + $titleH), $inner, $bodyH))
    foreach ($l in $laid) {
        $p = $l.P; $col = if ($p.Ok) { $green } else { $red }
        $tagW = [int]$g.MeasureString($p.Tag, $tagFont).Width + 24
        $g.FillRectangle((& $brush $col), 40, $l.Y, $tagW, 38)
        $g.DrawString($p.Tag, $tagFont, [System.Drawing.Brushes]::White, 50, ($l.Y + 1))
        $top = $l.Y + 44
        if ($p.Note) { $g.DrawString($p.Note, $noteFont, (& $brush $col), (New-Object System.Drawing.RectangleF 40, $top, $inner, $l.NoteH)); $top += $l.NoteH }
        $dest = New-Object System.Drawing.Rectangle 40, $top, $l.W, $l.H
        if ($p.Pixelated) { $g.InterpolationMode = 'NearestNeighbor'; $g.PixelOffsetMode = 'Half' }
        $g.DrawImage($l.Img, $dest, (New-Object System.Drawing.Rectangle $l.C[0], $l.C[1], $l.C[2], $l.C[3]), 'Pixel')
        $g.InterpolationMode = 'HighQualityBicubic'; $g.PixelOffsetMode = 'Default'
        $g.DrawRectangle((New-Object System.Drawing.Pen ([System.Drawing.Color]::FromArgb(200, 200, 205)), 1), $dest)
        $pen = New-Object System.Drawing.Pen $col, 5
        foreach ($m in $p.Marks) {
            $g.DrawRectangle($pen, [int](40 + ($m[0] - $l.C[0]) * $p.Scale), [int]($top + ($m[1] - $l.C[1]) * $p.Scale), [int]($m[2] * $p.Scale), [int]($m[3] * $p.Scale))
        }
    }
    $bmp.Save("$dst\$name.png"); $g.Dispose(); $bmp.Dispose()
    foreach ($l in $laid) { $l.Img.Dispose() }
    "$dst\$name.png  height $y"
}

Compose 'Bug-1-print-issues-cut-off' 'Bug 1: print issues are cut off when Windows is above 100% scale' `
  'The text doubles in size at 200%, but its white box stays its 100% width, so words are chopped off at the right edge. These are the warnings a person needs to read. There is no "correct" picture here: the box should simply be about twice as wide.' @(
  @{ File = "$src\1a-issue-bubble-clipped.png"; Crop = @(280, 100, 370, 420); Scale = 2; Tag = 'WRONG: one issue open'; Ok = $false
     Note = 'The heading''s "Why" link is chopped to "Wh".'; Marks = @(, @(536, 130, 54, 34)) },
  @{ File = "$src\1b-issue-list-clipped.png"; Crop = @(240, 110, 410, 210); Scale = 2; Tag = 'WRONG: two issues listed'; Ok = $false
     Note = 'The lines stop mid-word: "Relative extruder addres" and "20mm_cube.obj is too clo".'; Marks = @(@(560, 142, 56, 34), @(560, 208, 56, 34)) }
) 1100

Compose 'Bug-2-from-the-file-mark-missing' 'Bug 2: the printer chip doesn''t warn that the printer came from the file' `
  'Same 3MF both times, and the person has set up no printer. On a brand-new data folder the chip shows the file''s printer as if it were their own: no warning triangle, no "from the file", and a long name with the file''s name stuck on the end.' @(
  @{ File = "$src\2a-chip-no-mark-new-folder.png"; Crop = @(500, 0, 1400, 240); Scale = 1.2; Tag = 'WRONG: brand-new data folder, no Bambu profiles'; Ok = $false
     Note = 'A plain printer icon and the file''s name in the chip. The menu row below it treats this as a printer of yours.'; Marks = @(, @(806, 34, 660, 58)) },
  @{ File = "$src\2b-chip-marked-with-bambu-profiles.png"; Crop = @(500, 0, 1400, 130); Scale = 1.2; Tag = 'CORRECT: Bambu profiles installed'; Ok = $true
     Note = 'A warning triangle and the words "from the file".'; Marks = @(, @(850, 36, 570, 58)) }
)

Compose 'Bug-3-slice-blocked-on-new-folder' 'Bug 3: a new user can''t slice a Bambu 3MF (the worst one)' `
  'Same 3MF both times. On a brand-new data folder the Slice button stays grey, and the only explanation is a G-code error the person can''t act on. Once Bambu profiles are installed, the same file slices normally.' @(
  @{ File = "$src\3-slice-blocked-new-folder.png"; Crop = @(2200, 60, 1256, 1440); Scale = 1.0; Tag = 'WRONG: brand-new data folder'; Ok = $false
     Note = 'Slice is grey. The error at the bottom of the note asks them to add "G92 E0" to layer_gcode.'; Marks = @(@(2300, 86, 190, 76), @(2680, 1235, 700, 200)) },
  @{ File = 'C:\b\wk7\b1-tape.png'; Crop = @(2200, 60, 1256, 660); Scale = 1.0; Tag = 'CORRECT: Bambu profiles installed'; Ok = $true
     Note = 'Slice is purple and ready to press, and there is no error.'; Marks = @(, @(2300, 86, 190, 76)) }
) 1340

Compose 'Bug-4-false-settings-changed' 'Bug 4: a project nobody edited says "3 settings changed" (minor, leave for now)' `
  'I imported a cube, changed nothing, and reopened the project from Home. Only happens on the placeholder "Default Printer"; a Bambu printer showed no false count.' @(
  @{ File = "$src\4a-reopened-says-3-changed.png"; Crop = @(900, 30, 2556, 290); Scale = 0.68; Tag = 'WRONG: the header and setup card'; Ok = $false
     Note = 'The printer has a * meaning "modified", and the card claims 3 settings changed.'; Marks = @(@(1040, 60, 230, 50), @(2990, 182, 260, 50)) },
  @{ File = "$src\4b-changed-list-shows-1.png"; Crop = $null; Scale = 1.6; Tag = 'WRONG: the list of what changed'; Ok = $false
     Note = 'Only 1 setting is listed, not 3, and the only difference is one space after the comma.'; Marks = @(@(520, 92, 340, 44), @(300, 225, 560, 150)) }
)

Compose 'Bug-5-ring-looks-solid-at-100' 'Bug 5: the "Not connected" ring looks solid at 100% scale (cosmetic, leave it)' `
  'The ring should be dashed. At 8 pixels there isn''t room for gaps at 100%. Enlarged here so the pixels show; on screen each ring is tiny, and "Not connected" is written right beside it. The left half comes from the test harness''s drawing at 100%, because this session is now at 200%.' @(
  @{ File = "$src\5-ring-100pct-left-200pct-right.png"; Crop = @(20, 20, 720, 340); Scale = 1.5; Tag = 'LEFT is 100% (solid) and RIGHT is 200% (dashed, correct)'; Ok = $false; Pixelated = $true; Marks = @() }
) 1200

