27	namespace Slic3r::GUI::JusPrin::PrintIssues {
28	
29	// One frame's sizes and colours, read once from the theme.
30	struct IssueOverlay::Style
31	{
32	    const ShellMetrics& m;
33	    const ShellPalette& p;
34	    float scale, canvas_w, canvas_h;
35	    float inset, pad, gap, line, dot;
36	    // The icon button recipe: its side and the icon inside it.
37	    float icon_button;
38	    int   icon;
39	};
40	
41	// Bound to the canvas's window after the canvas bound its own handlers, so
42	// wxWidgets calls these first. The window forgets a handler object that is
43	// destroyed, so nothing is unbound by hand.
44	class IssueOverlay::Input final : public wxEvtHandler
45	{
46	public:
47	    Input(IssueOverlay& overlay, wxWindow& window) : m_overlay(overlay)
48	    {
49	        window.Bind(wxEVT_CHAR, &Input::on_char, this);
50	        window.Bind(wxEVT_LEFT_DOWN, &Input::on_press, this);
51	        window.Bind(wxEVT_MIDDLE_DOWN, &Input::on_press, this);
52	        window.Bind(wxEVT_RIGHT_DOWN, &Input::on_press, this);
53	    }
54	
55	private:
56	    void on_char(wxKeyEvent& event)
57	    {
58	        // Escape closes one thing at a time: what it closed here it does not
59	        // also deselect in the canvas.
60	        if (event.GetKeyCode() != WXK_ESCAPE || !m_overlay.on_escape())
61	            event.Skip();
62	    }
63	    void on_press(wxMouseEvent& event)
64	    {
65	        // The canvas scales the pointer the same way before ImGui sees it.
66	        const float scale = m_overlay.m_canvas.get_scale();
67	        m_overlay.on_pointer_down(float(event.GetX()) * scale, float(event.GetY()) * scale);
68	        event.Skip(); // the press is still the canvas's
69	    }
70	
71	    IssueOverlay& m_overlay;
72	};
73	
