188	// What the status counts: the issues nobody asked it to leave out.
189	struct Tally
190	{
191	    std::size_t counted{0}, current{0}, blockers{0}, ignored{0};
192	};
193	
194	Tally tally(const PrintIssueSnapshot& snapshot)
195	{
196	    Tally t;
197	    for (const PrintIssue& issue : snapshot.issues) {
198	        t.ignored += issue.ignored ? 1 : 0;
199	        t.counted += issue.ignored ? 0 : 1;
200	        t.current += !issue.ignored && !issue.stale ? 1 : 0;
201	        t.blockers += !issue.stale && issue.severity == IssueSeverity::Blocker ? 1 : 0;
202	    }
203	    return t;
204	}
