206	std::string checking_label() { return _u8L("Checking..."); }
207	std::string plate_label() { return _u8L("Whole plate"); }
208	std::string ignored_label() { return _u8L("Ignored"); }
209	
210	// What the pill says while there is an issue to say it about.
211	std::string status_label(const PrintIssueSnapshot& snapshot, const Tally& t)
212	{
213	    if (!snapshot.checked)
214	        return checking_label();
215	    // Nothing left that counts, and still not all clear: say what was done.
216	    if (t.counted == 0)
217	        return format_wxstr(_L_PLURAL("%1% warning ignored", "%1% warnings ignored", int(t.ignored)), t.ignored).ToUTF8().data();
218	    const int count = int(t.counted);
219	    std::string label = format_wxstr(_L_PLURAL("%1% print issue", "%1% print issues", count), count).ToUTF8().data();
220	    if (t.blockers != 0)
221	        label += " \xC2\xB7 " + format(_u8L("%1% blocking"), t.blockers);
222	    return label;
223	}
