568	void IssueOverlay::draw_list(const Style& s, const StatusLayout& layout, const PrintIssueSnapshot& snapshot, float row_height)
569	{
570	    const OverlayRect& list = layout.list;
571	    m_frame.list_open = true;
572	    m_frame.list      = list;
573	
574	    // A real ImGui window rather than a bare one: with more issues than the
575	    // canvas has room for, it scrolls.
576	    ImGui::SetNextWindowPos(ImVec2(list.x, list.y));
577	    ImGui::SetNextWindowSize(ImVec2(list.w, list.h));
578	    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(std::round((s.m.menu_row.side_inset + s.m.popover.border_width) * s.scale), std::round(s.m.popover.padding_y * s.scale)));
579	    ImGui::PushStyleVar(ImGuiStyleVar_WindowBorderSize, std::round(s.m.popover.border_width * s.scale));
580	    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, std::round(s.m.popover.radius * s.scale));
581	    ImGui::PushStyleVar(ImGuiStyleVar_WindowMinSize, ImVec2(0.f, 0.f));
582	    ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(0.f, 0.f));
583	    ImGui::PushStyleColor(ImGuiCol_WindowBg, im_vec(s.p.surface_raised));
584	    ImGui::PushStyleColor(ImGuiCol_Border, im_vec(s.p.border_subtle));
585	    ImGui::Begin("##jusprin_issue_list", nullptr,
586	                 ImGuiWindowFlags_NoTitleBar | ImGuiWindowFlags_NoResize | ImGuiWindowFlags_NoMove | ImGuiWindowFlags_NoCollapse |
587	                     ImGuiWindowFlags_NoSavedSettings | ImGuiWindowFlags_NoFocusOnAppearing | ImGuiWindowFlags_NoNav);
588	    ImGui::BringWindowToDisplayFront(ImGui::GetCurrentWindow());
589	
590	    // The ones that count first; an ignored warning stays within reach below.
591	    std::vector<const PrintIssue*> rows;
592	    for (const bool ignored : {false, true})
593	        for (const PrintIssue& issue : snapshot.issues)
594	            if (issue.ignored == ignored)
595	                rows.push_back(&issue);
596	
597	    ImDrawList& draw = *ImGui::GetWindowDrawList();
598	    int index = 0;
599	    for (const PrintIssue* row : rows) {
600	        const PrintIssue& issue = *row;
601	        ImGui::PushID(index++);
602	        const bool clicked = ImGui::InvisibleButton("##row", ImVec2(ImGui::GetContentRegionAvail().x, row_height));
603	        ImGui::PopID();
604	        const ImVec2 min = ImGui::GetItemRectMin(), max = ImGui::GetItemRectMax();
605	        m_frame.rows.emplace_back(issue.id, OverlayRect{min.x, min.y, max.x - min.x, max.y - min.y});
606	        // The list is a menu: its row under the pointer is a menu row's.
607	        if (ImGui::IsItemHovered())
608	            draw.AddRectFilled(min, max, im_color(s.p.surface_raised_hover), std::round(s.m.menu_row.radius * s.scale));
609	        draw.AddCircleFilled(ImVec2(min.x + s.pad / 2 + s.dot / 2, (min.y + max.y) / 2), s.dot / 2, im_color(tone(issue, s.p)));
610	        const float text_x = min.x + s.pad / 2 + s.dot + s.gap;
611	        const float text_y = min.y + std::round((row_height - 2 * s.line) / 2);
612	        const std::string where = (issue.object_name.empty() ? plate_label() : issue.object_name) +
613	                                  (issue.ignored ? " \xC2\xB7 " + ignored_label() : std::string()) +
614	                                  (issue.stale ? " \xC2\xB7 " + checking_label() : std::string());
615	        draw.PushClipRect(ImVec2(text_x, min.y), ImVec2(max.x - s.gap, max.y), true);
616	        draw.AddText(ImVec2(text_x, text_y), im_color(issue.ignored ? s.p.text_secondary : s.p.text_primary), first_line(issue.message).c_str());
617	        draw.AddText(ImVec2(text_x, text_y + s.line), im_color(s.p.text_secondary), where.c_str());
618	        draw.PopClipRect();
619	        if (clicked)
620	            after_frame([id = issue.id](IssueOverlay& self) { self.select(id); });
621	    }
622	
623	    ImGui::End();
624	    ImGui::PopStyleColor(2);
625	    ImGui::PopStyleVar(5);
626	}
