732	    draw.AddText(ImVec2(bubble.x + s.pad + s.dot + s.gap, y), im_color(s.p.text_primary), severity.c_str());
733	    const ImVec2 severity_size = ImGui::CalcTextSize(severity.c_str());
734	    draw.PushClipRect(ImVec2(bubble.x, bubble.y), ImVec2(close.x, bubble.y + bubble.h), true);
735	    draw.AddText(ImVec2(bubble.x + s.pad + s.dot + s.gap + severity_size.x + s.gap, y), im_color(s.p.text_secondary), where.c_str());
736	    draw.PopClipRect();
737	    y += s.line + s.gap;
738	    draw.AddText(ImGui::GetFont(), ImGui::GetFontSize(), ImVec2(bubble.x + s.pad, y), im_color(s.p.text_primary), message.c_str(), nullptr, wrap);
739	    y += message_size.y;
740	    if (!note.empty()) {
741	        y += s.gap;
742	        draw.AddText(ImVec2(bubble.x + s.pad, y), im_color(s.p.text_secondary), note.c_str());
743	        y += s.line;
744	    }
745	    y += s.pad;
746	
747	    if (ready) {
748	        const OverlayRect ask{bubble.x + s.pad, y, bubble.w - 2 * s.pad, button_h};
749	        m_frame.ask = ask;
750	        // One question, and the agent may then fix what the person asks it
751	        // to: a second "fix" button sent the same context with the same tools.
752	        // A press that reached the chat closes the bubble: the answer is there.
753	        if (button(draw, "##ask", ask, _u8L("Ask AI"), std::round(recipe.radius * s.scale), enabled, s.p.action_primary,
754	                   s.p.action_primary_hover, s.p.action_primary_text, nullptr, s.p))
755	            after_frame([id = issue.id](IssueOverlay& self) {
756	                if (self.m_actions.submit && self.m_actions.submit(id, _u8L("Explain this issue and my options.")) && self.m_selected == id)
757	                    self.close_bubble();
758	            });
759	    } else {
760	        // Nothing Ask AI promises could happen yet, so the button in its
761	        // place leads to where the agent is set up. It needs no checked issue
762	        // and leaves the bubble open behind the window. Three dots: the
