778	        if (link(draw, "##ignore", rect, ignore, s.p))
779	            after_frame([id = issue.id, ignored = !issue.ignored](IssueOverlay& self) {
780	                self.m_monitor.set_ignored(id, ignored);
781	                // Ignored is dealt with; shown again is something to read.
782	                if (ignored && self.m_selected == id)
783	                    self.close_bubble();
784	            });
785	    }
786	    if (paged) {
787	        const ImVec2      pager_size = ImGui::CalcTextSize(pager.c_str());
788	        const OverlayRect next{right - s.icon_button, y, s.icon_button, s.icon_button};
