790	        const OverlayRect previous{text_x - s.icon_button, y, s.icon_button, s.icon_button};
791	        m_frame.previous = previous;
792	        m_frame.next     = next;
793	        draw.AddText(ImVec2(text_x, y + std::round((footer_h - pager_size.y) / 2)), im_color(s.p.text_secondary), pager.c_str());
794	        const auto turn = [this, &walk, walk_index](int by) {
795	            const int count = int(walk.size());
796	            after_frame([id = walk[(walk_index + by + count) % count]->id](IssueOverlay& self) { self.select(id); });
797	        };
798	        if (icon_button(draw, "##previous", previous, "chevron-left", s.icon, icon_radius, s.p))
799	            turn(-1);
800	        if (icon_button(draw, "##next", next, "chevron-right", s.icon, icon_radius, s.p))
801	            turn(1);
802	    }
803	    draw.PopClipRect();
804	    ImGui::End();
