1	// Scratch DevTools driver for the WebView2 pages.
2	//   node cdp.mjs list
3	//   node cdp.mjs eval <urlSubstring> <js>
4	//   node cdp.mjs shot <urlSubstring> <out.png>
5	import { writeFileSync } from 'node:fs';
6	
7	const [, , command, match, arg] = process.argv;
8	const targets = await (await fetch('http://127.0.0.1:9333/json/list')).json();
9	if (command === 'list') {
10	  for (const t of targets) console.log(t.type, t.url.slice(0, 120), t.title);
11	  process.exit(0);
12	}
13	const pages = targets.filter((t) => t.type === 'page' && t.url.includes(match));
14	if (pages.length === 0) {
15	  console.error('no page matches', match);
16	  process.exit(2);
17	}
18	const socket = new WebSocket(pages[0].webSocketDebuggerUrl);
19	await new Promise((resolve) => socket.addEventListener('open', resolve));
20	let next = 0;
21	const call = (method, params = {}) =>
22	  new Promise((resolve, reject) => {
23	    const id = ++next;
24	    const listener = (event) => {
25	      const message = JSON.parse(event.data);
26	      if (message.id !== id) return;
27	      socket.removeEventListener('message', listener);
28	      message.error ? reject(new Error(JSON.stringify(message.error))) : resolve(message.result);
29	    };
30	    socket.addEventListener('message', listener);
31	    socket.send(JSON.stringify({ id, method, params }));
32	  });
33	if (command === 'eval') {
34	  const result = await call('Runtime.evaluate', { expression: arg, awaitPromise: true, returnByValue: true });
35	  console.log(JSON.stringify(result.result.value ?? result.exceptionDetails ?? result.result, null, 1));
36	} else if (command === 'type') {
37	  // Focus the composer, type as a keyboard does, then Enter.
38	  await call('Runtime.evaluate', { expression: "document.querySelector('textarea').focus()" });
39	  await call('Input.insertText', { text: arg });
40	  for (const type of ['keyDown', 'keyUp'])
41	    await call('Input.dispatchKeyEvent', { type, key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, text: type === 'keyDown' ? '\r' : undefined });
42	  console.log('typed', arg);
43	} else if (command === 'shot') {
44	  const result = await call('Page.captureScreenshot', { format: 'png' });
45	  writeFileSync(arg, Buffer.from(result.data, 'base64'));
46	  console.log('wrote', arg);
47	}
48	socket.close();
49	process.exit(0);
