106	AgentServicePtr make_provider_agent(const ProviderProfile&               profile,
107	                                    const std::string&                   api_key,
108	                                    const std::string&                   model,
109	                                    const std::string&                   endpoint,
110	                                    std::unique_ptr<IAgentHttpTransport> transport,
111	                                    ProviderListeners                    listeners)
112	{
113	    ProviderAgentConfig config;
114	    config.profile = profile;
115	    if (!model.empty())
116	        config.profile.model = model;
117	    if (!endpoint.empty())
118	        config.profile.endpoint = endpoint;
119	    config.api_key          = api_key;
120	    config.usage_listener   = std::move(listeners.usage);
121	    config.refusal_listener = std::move(listeners.refusal);
122	    config.request_listener = std::move(listeners.request);
123	    return std::make_unique<ProviderAgent>(std::move(config), codec_for(profile.family), std::move(transport));
124	}
