131	PrintIssueMonitor::~PrintIssueMonitor()
132	{
133	    wxASSERT(wxIsMainThread());
134	    set_notifications_listener({});
135	    m_plater.Unbind(EVT_PROCESS_COMPLETED, &PrintIssueMonitor::on_process_completed, this);
136	}
