138	void PrintIssueMonitor::on_process_completed(SlicingProcessCompletedEvent& event)
139	{
140	    event.Skip();
141	    if (!event.error())
142	        return;
143	    PartPlate* plate = m_plater.get_partplate_list().get_curr_plate();
144	    if (plate == nullptr)
145	        return;
146	    SliceFailure failure;
147	    const auto   message = event.format_error_message();
148	    failure.message  = message.first;
149	    failure.critical = event.critical_error();
150	    // The same lookup OrcaSlicer's own handler makes: an id that is not a
151	    // print object's names nothing.
152	    if (const Print* print = plate->fff_print())
153	        for (const std::size_t id : message.second)
154	            if (const PrintObject* object = print->get_object(ObjectID(id)); object != nullptr && object->model_object() != nullptr)
155	                failure.objects.push_back(object->model_object()->id().id);
156	    m_failures[plate->id().id] = std::move(failure);
157	    m_looked = false; // nothing else may have moved; the next turn rebuilds
158	}
