param([byte]$Vk, [int]$Times = 1, [switch]$Extended)
# Presses one key with real keyboard events; arrows need the extended flag.
Add-Type @"
using System; using System.Runtime.InteropServices;
public static class K9 { [DllImport("user32.dll")] public static extern void keybd_event(byte v, byte s, uint f, UIntPtr e); }
"@
$f = [uint32]$(if ($Extended) { 1 } else { 0 })
for ($i = 0; $i -lt $Times; $i++) {
  [K9]::keybd_event($Vk, 0, $f, [UIntPtr]::Zero); Start-Sleep -Milliseconds 40
  [K9]::keybd_event($Vk, 0, $f -bor 2, [UIntPtr]::Zero); Start-Sleep -Milliseconds 120
}

